     1→import {ChainForkConfig} from "@lodestar/config";
     2→import {IForkChoice, ProtoBlock} from "@lodestar/fork-choice";
     3→import {SLOTS_PER_EPOCH} from "@lodestar/params";
     4→import {
     5→  CachedBeaconStateAllForks,
     6→  DataAvailabilityStatus,
     7→  ExecutionPayloadStatus,
     8→  StateHashTreeRootSource,
     9→  computeEpochAtSlot,
    10→  computeStartSlotAtEpoch,
    11→  processSlots,
    12→  stateTransition,
    13→} from "@lodestar/state-transition";
    14→import {BeaconBlock, RootHex, SignedBeaconBlock, Slot, phase0} from "@lodestar/types";
    15→import {Logger, fromHex, toRootHex} from "@lodestar/utils";
    16→import {IBeaconDb} from "../../db/index.js";
    17→import {Metrics} from "../../metrics/index.js";
    18→import {nextEventLoop} from "../../util/eventLoop.js";
    19→import {getCheckpointFromState} from "../blocks/utils/checkpoint.js";
    20→import {ChainEvent, ChainEventEmitter} from "../emitter.js";
    21→import {BlockStateCache, CheckpointStateCache} from "../stateCache/types.js";
    22→import {ValidatorMonitor} from "../validatorMonitor.js";
    23→import {RegenError, RegenErrorCode} from "./errors.js";
    24→import {IStateRegeneratorInternal, RegenCaller, StateRegenerationOpts} from "./interface.js";
    25→
    26→export type RegenModules = {
    27→  db: IBeaconDb;
    28→  forkChoice: IForkChoice;
    29→  blockStateCache: BlockStateCache;
    30→  checkpointStateCache: CheckpointStateCache;
    31→  config: ChainForkConfig;
    32→  emitter: ChainEventEmitter;
    33→  logger: Logger;
    34→  metrics: Metrics | null;
    35→  validatorMonitor: ValidatorMonitor | null;
    36→};
    37→
    38→/**
    39→ * Regenerates states that have already been processed by the fork choice
    40→ * Since Feb 2024, we support reloading checkpoint state from disk via allowDiskReload flag. Due to its performance impact
    41→ * this flag is only set to true in this case:
    42→ *    - getPreState: this is for block processing, it's important to reload state in unfinality time
    43→ *    - updateHeadState: rarely happen, but it's important to make sure we always can regen head state
    44→ */
    45→export class StateRegenerator implements IStateRegeneratorInternal {
    46→  constructor(private readonly modules: RegenModules) {}
    47→
    48→  /**
    49→   * Get the state to run with `block`. May be:
    50→   * - If parent is in same epoch -> Exact state at `block.parentRoot`
    51→   * - If parent is in prev epoch -> State after `block.parentRoot` dialed forward through epoch transition
    52→   * - reload state if needed in this flow
    53→   */
    54→  async getPreState(
    55→    block: BeaconBlock,
    56→    opts: StateRegenerationOpts,
    57→    regenCaller: RegenCaller
    58→  ): Promise<CachedBeaconStateAllForks> {
    59→    const parentBlock = this.modules.forkChoice.getBlock(block.parentRoot);
    60→    if (!parentBlock) {
    61→      throw new RegenError({
    62→        code: RegenErrorCode.BLOCK_NOT_IN_FORKCHOICE,
    63→        blockRoot: block.parentRoot,
    64→      });
    65→    }
    66→
    67→    const parentEpoch = computeEpochAtSlot(parentBlock.slot);
    68→    const blockEpoch = computeEpochAtSlot(block.slot);
    69→    const allowDiskReload = true;
    70→
    71→    // This may save us at least one epoch transition.
    72→    // If the requested state crosses an epoch boundary
    73→    // then we may use the checkpoint state before the block
    74→    // We may have the checkpoint state with parent root inside the checkpoint state cache
    75→    // through gossip validation.
    76→    if (parentEpoch < blockEpoch) {
    77→      return this.getCheckpointState({root: block.parentRoot, epoch: blockEpoch}, opts, regenCaller, allowDiskReload);
    78→    }
    79→
    80→    // Otherwise, get the state normally.
    81→    return this.getState(parentBlock.stateRoot, regenCaller, opts, allowDiskReload);
    82→  }
    83→
    84→  /**
    85→   * Get state after block `cp.root` dialed forward to first slot of `cp.epoch`
    86→   */
    87→  async getCheckpointState(
    88→    cp: phase0.Checkpoint,
    89→    opts: StateRegenerationOpts,
    90→    regenCaller: RegenCaller,
    91→    allowDiskReload = false
    92→  ): Promise<CachedBeaconStateAllForks> {
    93→    const checkpointStartSlot = computeStartSlotAtEpoch(cp.epoch);
    94→    return this.getBlockSlotState(toRootHex(cp.root), checkpointStartSlot, opts, regenCaller, allowDiskReload);
    95→  }
    96→
    97→  /**
    98→   * Get state after block `blockRoot` dialed forward to `slot`
    99→   *   - allowDiskReload should be used with care, as it will cause the state to be reloaded from disk
   100→   */
   101→  async getBlockSlotState(
   102→    blockRoot: RootHex,
   103→    slot: Slot,
   104→    opts: StateRegenerationOpts,
   105→    regenCaller: RegenCaller,
   106→    allowDiskReload = false
   107→  ): Promise<CachedBeaconStateAllForks> {
   108→    const block = this.modules.forkChoice.getBlockHex(blockRoot);
   109→    if (!block) {
   110→      throw new RegenError({
   111→        code: RegenErrorCode.BLOCK_NOT_IN_FORKCHOICE,
   112→        blockRoot,
   113→      });
   114→    }
   115→
   116→    if (slot < block.slot) {
   117→      throw new RegenError({
   118→        code: RegenErrorCode.SLOT_BEFORE_BLOCK_SLOT,
   119→        slot,
   120→        blockSlot: block.slot,
   121→      });
   122→    }
   123→
   124→    const {checkpointStateCache} = this.modules;
   125→    const epoch = computeEpochAtSlot(slot);
   126→    const latestCheckpointStateCtx = allowDiskReload
   127→      ? await checkpointStateCache.getOrReloadLatest(blockRoot, epoch, opts)
   128→      : checkpointStateCache.getLatest(blockRoot, epoch, opts);
   129→
   130→    // If a checkpoint state exists with the given checkpoint root, it either is in requested epoch
   131→    // or needs to have empty slots processed until the requested epoch
   132→    if (latestCheckpointStateCtx) {
   133→      return processSlotsByCheckpoint(this.modules, latestCheckpointStateCtx, slot, regenCaller, opts);
   134→    }
   135→
   136→    // Otherwise, use the fork choice to get the stateRoot from block at the checkpoint root
   137→    // regenerate that state,
   138→    // then process empty slots until the requested epoch
   139→    const blockStateCtx = await this.getState(block.stateRoot, regenCaller, opts, allowDiskReload);
   140→    return processSlotsByCheckpoint(this.modules, blockStateCtx, slot, regenCaller, opts);
   141→  }
   142→
   143→  /**
   144→   * Get state by exact root. If not in cache directly, requires finding the block that references the state from the
   145→   * forkchoice and replaying blocks to get to it.
   146→   *   - allowDiskReload should be used with care, as it will cause the state to be reloaded from disk
   147→   */
   148→  async getState(
   149→    stateRoot: RootHex,
   150→    caller: RegenCaller,
   151→    opts?: StateRegenerationOpts,
   152→    // internal option, don't want to expose to external caller
   153→    allowDiskReload = false
   154→  ): Promise<CachedBeaconStateAllForks> {
   155→    // Trivial case, state at stateRoot is already cached
   156→    const cachedStateCtx = this.modules.blockStateCache.get(stateRoot, opts);
   157→    if (cachedStateCtx) {
   158→      return cachedStateCtx;
   159→    }
   160→
   161→    // in block gossip validation (getPreState() call), dontTransferCache is specified as true because we only want to transfer cache in verifyBlocksStateTransitionOnly()
   162→    // but here we want to process blocks as fast as possible so force to transfer cache in this case
   163→    if (opts && allowDiskReload) {
