   224→
   225→    const logCtx = {stateRoot, caller, replaySlots: replaySlots.join(",")};
   226→    this.modules.logger.debug("Replaying blocks to get state", logCtx);
   227→
   228→    const loadBlocksTimer = this.modules.metrics?.regenGetState.loadBlocks.startTimer({caller});
   229→    const blockOrNulls = await Promise.all(blockPromises);
   230→    loadBlocksTimer?.();
   231→
   232→    const blocksByRoot = new Map<RootHex, SignedBeaconBlock>();
   233→    for (const [i, blockOrNull] of blockOrNulls.entries()) {
   234→      // checking early here helps prevent unneccessary state transition below
   235→      if (blockOrNull === null) {
