   302→    return state;
   303→  }
   304→
   305→  private findFirstStateBlock(stateRoot: RootHex): ProtoBlock {
   306→    for (const block of this.modules.forkChoice.forwarditerateAncestorBlocks()) {
   307→      if (block.stateRoot === stateRoot) {
   308→        return block;
   309→      }
   310→    }
   311→
   312→    throw new RegenError({
   313→      code: RegenErrorCode.STATE_NOT_IN_FORKCHOICE,
   314→      stateRoot,
   315→    });
   316→  }
   317→}
   318→
   319→/**
   320→ * Starting at `state.slot`,
   321→ * process slots forward towards `slot`,
   322→ * emitting "checkpoint" events after every epoch processed.
   323→ */
   324→async function processSlotsByCheckpoint(
   325→  modules: {
   326→    checkpointStateCache: CheckpointStateCache;
   327→    metrics: Metrics | null;
   328→    validatorMonitor: ValidatorMonitor | null;
   329→    emitter: ChainEventEmitter;
