   338→  if (postState.slot < slot) {
   339→    postState = processSlots(postState, slot, opts, modules);
   340→  }
   341→  return postState;
   342→}
   343→
   344→/**
   345→ * Starting at `state.slot`,
   346→ * process slots forward towards `slot`,
   347→ * emitting "checkpoint" events after every epoch processed.
   348→ *
   349→ * Stops processing after no more full epochs can be processed.
   350→ */
   351→export async function processSlotsToNearestCheckpoint(
   352→  modules: {
   353→    checkpointStateCache: CheckpointStateCache;
   354→    metrics: Metrics | null;
   355→    validatorMonitor: ValidatorMonitor | null;
   356→    emitter: ChainEventEmitter | null;
   357→    logger: Logger | null;
   358→  },
   359→  preState: CachedBeaconStateAllForks,
   360→  slot: Slot,
   361→  regenCaller: RegenCaller,
   362→  opts: StateRegenerationOpts
   363→): Promise<CachedBeaconStateAllForks> {
   364→  const preSlot = preState.slot;
   365→  const postSlot = slot;
   366→  const preEpoch = computeEpochAtSlot(preSlot);
   367→  let postState = preState;
   368→  const {checkpointStateCache, emitter, metrics, logger} = modules;
   369→  let count = 0;
   370→
   371→  for (
   372→    let nextEpochSlot = computeStartSlotAtEpoch(preEpoch + 1);
   373→    nextEpochSlot <= postSlot;
   374→    nextEpochSlot += SLOTS_PER_EPOCH
   375→  ) {
   376→    logger?.verbose("Processing slots over epochs", {
   377→      slot: postState.slot,
   378→      nextEpochSlot,
   379→      postSlot,
   380→      caller: regenCaller,
   381→    });
