   386→    // this is usually added when we prepare for next slot or validate gossip block
   387→    // then when we process the 1st block of epoch, we don't have to do state transition again
   388→    // This adds Previous Root Checkpoint State to the checkpoint state cache
   389→    // This may becomes the "official" checkpoint state if the 1st block of epoch is skipped
   390→    const checkpointState = postState;
   391→    const cp = getCheckpointFromState(checkpointState);
   392→    checkpointStateCache.add(cp, checkpointState);
   393→    // consumers should not mutate or get the transfered cache
   394→    emitter?.emit(ChainEvent.checkpoint, cp, checkpointState.clone(true));
