   397→      // in normal condition, we only process 1 epoch so never reach this
   398→      // in that case, we want to prune state at the last 1/3 slot of slot 0 of the next epoch after importing the 1st block of epoch
   399→      // in non-finality time, we may process a lot of epochs so need to prune the cache to keep the node healthy
   400→      // this happened to holesky on Feb 2025, see https://github.com/ChainSafe/lodestar/issues/7495#issuecomment-2680800898
   401→      // cannot use getBlockRootAtSlot() because nextEpochSlot = postState
   402→      const latestBlockHex = toRootHex(cp.root);
