   404→        const persistCount = await checkpointStateCache.processState(latestBlockHex, checkpointState);
   405→        logger?.verbose("pruning checkpointStateCache during processSlotsToNearestCheckpoint", {
   406→          root: latestBlockHex,
   407→          epoch: cp.epoch,
   408→          persistCount,
   409→        });
   410→      } catch (e) {
   411→        logger?.debug(
   412→          "CheckpointStateCache failed to process checkpoint state",
   413→          {root: latestBlockHex, epoch: cp.epoch},
   414→          e as Error
   415→        );
   416→      }
   417→    }
   418→    count++;
   419→
   420→    // this avoids keeping our node busy processing blocks
   421→    await nextEventLoop();
   422→  }
   423→  return postState;
